+import { render, screen } from "@testing-library/react";
+import { describe, it, expect, vi } from "vitest";
+import type { VereinData } from "@/lib/data/verein";
+
+// Mock the module that provides club data.
+// Use made-up test data so tests do not depend on the real sample data.
+const MOCK_VEREIN_DATA: VereinData = {
+  clubName: "Test Sportclub Musterstadt e.V.",
+  address: {
+    name: "Test Sportclub Musterstadt e.V.",
+    additional: "c/o Erika Musterfrau",
+    street: "Musterweg 42",
+    zip: "12345",
+    city: "Musterstadt",
+  },
+  email: "info@testclub.example",
+  phone: "+49 30 1234567",
+  board: [
+    {
+      role: "Vorsitzende",
+      name: "Erika Musterfrau",
+      email: "vorsitz@testclub.example",
+    },
+    {
+      role: "Stellvertreter",
+      name: "Hans Beispielmann",
+      email: "hans@testclub.example",
+    },
+    {
+      role: "Kassenwartin",
+      name: "Lisa Testkind",
+      email: "kasse@testclub.example",
+    },
+  ],
+  contentResponsible: {
+    name: "Erika Musterfrau",
+    role: "Vorsitzende",
+    clubName: "Test Sportclub Musterstadt e.V.",
+    address: {
+      name: "Test Sportclub Musterstadt e.V.",
+      additional: "",
+      street: "Musterweg 42",
+      zip: "12345",
+      city: "Musterstadt",
+    },
+    email: "vorsitz@testclub.example",
+  },
+  register: {
+    court: "Amtsgericht Musterstadt",
+    number: "VR 99999",
+  },
+  disclaimer:
+    "Dies ist ein Test-Haftungshinweis. Keine Haftung fuer externe Links.",
+};
+
+vi.mock("@/lib/data/verein", () => ({
+  VEREIN_DATA: MOCK_VEREIN_DATA,
+}));
+
+// Import after vi.mock so the mock is in place
+import Page from "@/app/impressum/page";
+
+describe("Impressum page", () => {
+  // ---------------------------------------------------------------------------
+  // C10: The page renders without errors (basic render test)
+  // ---------------------------------------------------------------------------
+  it("C10: renders without crashing", () => {
+    expect(() => {
+      render(<Page />);
+    }).not.toThrow();
+  });
+
+  // ---------------------------------------------------------------------------
+  // C1: Page renders the club name
+  // ---------------------------------------------------------------------------
+  it("C1: displays the club name", () => {
+    render(<Page />);
+    // The club name should appear at least once (in the TMG section)
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.clubName),
+    ).toBeInTheDocument();
+  });
+
+  it("C1: displays the club name exactly as provided in VEREIN_DATA", () => {
+    render(<Page />);
+    const nameElements = screen.getAllByText(MOCK_VEREIN_DATA.clubName);
+    expect(nameElements.length).toBeGreaterThanOrEqual(1);
+  });
+
+  // ---------------------------------------------------------------------------
+  // C2: Section "Angaben gemäß § 5 TMG" with address, email and phone
+  // ---------------------------------------------------------------------------
+  it("C2: has a section with heading 'Angaben gemäß § 5 TMG'", () => {
+    render(<Page />);
+    expect(
+      screen.getByRole("heading", {
+        name: /Angaben gemäß § 5 TMG/i,
+      }),
+    ).toBeInTheDocument();
+  });
+
+  it("C2: shows the full address in the TMG section", () => {
+    render(<Page />);
+    // Address components from VEREIN_DATA
+    expect(screen.getByText(MOCK_VEREIN_DATA.address.additional)).toBeInTheDocument();
+    expect(screen.getByText(MOCK_VEREIN_DATA.address.street)).toBeInTheDocument();
+    expect(
+      screen.getByText(
+        `${MOCK_VEREIN_DATA.address.zip} ${MOCK_VEREIN_DATA.address.city}`,
+      ),
+    ).toBeInTheDocument();
+  });
+
+  it("C2: shows the general email address in the TMG section", () => {
+    render(<Page />);
+    expect(screen.getByText(MOCK_VEREIN_DATA.email)).toBeInTheDocument();
+  });
+
+  it("C2: shows the phone number in the TMG section", () => {
+    render(<Page />);
+    expect(screen.getByText(MOCK_VEREIN_DATA.phone)).toBeInTheDocument();
+  });
+
+  // ---------------------------------------------------------------------------
+  // C3: Section "Vorstand" with all three board members and emails
+  // ---------------------------------------------------------------------------
+  it("C3: has a section with heading 'Vorstand'", () => {
+    render(<Page />);
+    expect(
+      screen.getByRole("heading", { name: /Vorstand/i }),
+    ).toBeInTheDocument();
+  });
+
+  it("C3: displays all three board member names", () => {
+    render(<Page />);
+    for (const member of MOCK_VEREIN_DATA.board) {
+      expect(screen.getByText(member.name)).toBeInTheDocument();
+    }
+  });
+
+  it("C3: displays each board member's role", () => {
+    render(<Page />);
+    for (const member of MOCK_VEREIN_DATA.board) {
+      expect(screen.getByText(member.role)).toBeInTheDocument();
+    }
+  });
+
+  it("C3: each board member email is shown on the page", () => {
+    render(<Page />);
+    for (const member of MOCK_VEREIN_DATA.board) {
+      expect(screen.getByText(member.email)).toBeInTheDocument();
+    }
+  });
+
+  // ---------------------------------------------------------------------------
+  // C4: Section "Inhaltlich Verantwortlicher" with name and address
+  // ---------------------------------------------------------------------------
+  it("C4: has a section heading containing 'Inhaltlich Verantwortlicher'", () => {
+    render(<Page />);
+    expect(
+      screen.getByRole("heading", {
+        name: /Inhaltlich Verantwortlicher/i,
+      }),
+    ).toBeInTheDocument();
+  });
+
+  it("C4: shows the content-responsible person's name", () => {
+    render(<Page />);
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.contentResponsible.name),
+    ).toBeInTheDocument();
+  });
+
+  it("C4: shows the content-responsible person's address", () => {
+    render(<Page />);
+    const cr = MOCK_VEREIN_DATA.contentResponsible;
+    expect(screen.getByText(cr.address.street)).toBeInTheDocument();
+    expect(
+      screen.getByText(`${cr.address.zip} ${cr.address.city}`),
+    ).toBeInTheDocument();
+  });
+
+  // ---------------------------------------------------------------------------
+  // C5: Section "Registereintrag" with court and register number
+  // ---------------------------------------------------------------------------
+  it("C5: has a section with heading 'Registereintrag'", () => {
+    render(<Page />);
+    expect(
+      screen.getByRole("heading", { name: /Registereintrag/i }),
+    ).toBeInTheDocument();
+  });
+
+  it("C5: shows the register court", () => {
+    render(<Page />);
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.register.court),
+    ).toBeInTheDocument();
+  });
+
+  it("C5: shows the register number", () => {
+    render(<Page />);
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.register.number),
+    ).toBeInTheDocument();
+  });
+
+  // ---------------------------------------------------------------------------
+  // C6: Section "Haftungshinweis" with the full disclaimer text
+  // ---------------------------------------------------------------------------
+  it("C6: has a section with heading 'Haftungshinweis'", () => {
+    render(<Page />);
+    expect(
+      screen.getByRole("heading", { name: /Haftungshinweis/i }),
+    ).toBeInTheDocument();
+  });
+
+  it("C6: shows the full disclaimer text", () => {
+    render(<Page />);
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.disclaimer),
+    ).toBeInTheDocument();
+  });
+
+  // ---------------------------------------------------------------------------
+  // C7: All email addresses are clickable mailto: links
+  // ---------------------------------------------------------------------------
+  it("C7: the general email is a clickable mailto link", () => {
+    render(<Page />);
+    const link = screen.getByRole("link", {
+      name: MOCK_VEREIN_DATA.email,
+    });
+    expect(link).toBeInTheDocument();
+    expect(link).toHaveAttribute(
+      "href",
+      `mailto:${MOCK_VEREIN_DATA.email}`,
+    );
+  });
+
+  it("C7: each board member email is a clickable mailto link", () => {
+    render(<Page />);
+    for (const member of MOCK_VEREIN_DATA.board) {
+      const link = screen.getByRole("link", { name: member.email });
+      expect(link).toBeInTheDocument();
+      expect(link).toHaveAttribute("href", `mailto:${member.email}`);
+    }
+  });
+
+  it("C7: every mailto link on the page starts with 'mailto:'", () => {
+    render(<Page />);
+    const allLinks = screen.getAllByRole("link");
+    const mailtoLinks = allLinks.filter((link) =>
+      (link.getAttribute("href") ?? "").startsWith("mailto:"),
+    );
+    // There should be at least: 1 general + 3 board + 1 content-responsible = 5
+    expect(mailtoLinks.length).toBeGreaterThanOrEqual(5);
+  });
+
+  // ---------------------------------------------------------------------------
+  // C11: Proper heading hierarchy (h1 for "Impressum", h2 for each section)
+  // ---------------------------------------------------------------------------
+  it("C11: has a top-level h1 heading 'Impressum'", () => {
+    render(<Page />);
+    const h1 = screen.getByRole("heading", { level: 1 });
+    expect(h1).toBeInTheDocument();
+    expect(h1).toHaveTextContent(/Impressum/i);
+  });
+
+  it("C11: each section uses an h2 heading", () => {
+    render(<Page />);
+    const h2s = screen.getAllByRole("heading", { level: 2 });
+    const h2Texts = h2s.map((h) => h.textContent);
+
+    // All five required sections should be present as h2
+    expect(
+      h2s.some((h) => /Angaben gemäß § 5 TMG/i.test(h.textContent ?? "")),
+    ).toBe(true);
+    expect(
+      h2s.some((h) => /Vorstand/i.test(h.textContent ?? "")),
+    ).toBe(true);
+    expect(
+      h2s.some((h) =>
+        /Inhaltlich Verantwortlicher/i.test(h.textContent ?? ""),
+      ),
+    ).toBe(true);
+    expect(
+      h2s.some((h) => /Registereintrag/i.test(h.textContent ?? "")),
+    ).toBe(true);
+    expect(
+      h2s.some((h) => /Haftungshinweis/i.test(h.textContent ?? "")),
+    ).toBe(true);
+  });
+
+  // ---------------------------------------------------------------------------
+  // C12: Proper semantic HTML structure
+  // ---------------------------------------------------------------------------
+  it("C12: the page is wrapped in a <main> element", () => {
+    render(<Page />);
+    expect(screen.getByRole("main")).toBeInTheDocument();
+  });
+
+  it("C12: each section uses semantic <section> elements or equivalent landmarks", () => {
+    render(<Page />);
+    // There should be at least 5 sections (TMG, Vorstand, Verantwortlicher, Register, Haftung)
+    const sections = screen.getAllByRole("region", { hidden: false });
+    // Sections with aria-labelledby or <section> elements with headings are regions
+    // Alternatively, count <section> elements directly
+    const sectionElements = document.querySelectorAll("section");
+    expect(sectionElements.length).toBeGreaterThanOrEqual(5);
+  });
+
+  // ---------------------------------------------------------------------------
+  // C9: Page metadata title
+  // The metadata export is tested by importing the module and checking the export.
+  // ---------------------------------------------------------------------------
+  it("C9: exports metadata with title 'Impressum – Sportverein Grünwiese e.V.'", async () => {
+    const pageModule = await import("@/app/impressum/page");
+    // The metadata may be exported directly (Next.js convention) or as a const
+    const meta = (pageModule as { metadata?: { title?: string } }).metadata;
+    expect(meta).toBeDefined();
+    expect(meta?.title).toBe("Impressum – Sportverein Grünwiese e.V.");
+  });
+
+  // ---------------------------------------------------------------------------
+  // N1: Legal compliance – Impressum contains required information
+  // ---------------------------------------------------------------------------
+  it("N1: shows the club name (legal compliance)", () => {
+    render(<Page />);
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.clubName),
+    ).toBeInTheDocument();
+  });
+
+  it("N1: shows the address (legal compliance)", () => {
+    render(<Page />);
+    expect(screen.getByText(MOCK_VEREIN_DATA.address.street)).toBeInTheDocument();
+    expect(
+      screen.getByText(
+        `${MOCK_VEREIN_DATA.address.zip} ${MOCK_VEREIN_DATA.address.city}`,
+      ),
+    ).toBeInTheDocument();
+  });
+
+  it("N1: shows authorised representatives / board (legal compliance)", () => {
+    render(<Page />);
+    // Vorstand section heading exists
+    expect(
+      screen.getByRole("heading", { name: /Vorstand/i }),
+    ).toBeInTheDocument();
+    // All board members are listed
+    for (const member of MOCK_VEREIN_DATA.board) {
+      expect(screen.getByText(member.name)).toBeInTheDocument();
+    }
+  });
+
+  it("N1: shows contact details – email and phone (legal compliance)", () => {
+    render(<Page />);
+    expect(screen.getByText(MOCK_VEREIN_DATA.email)).toBeInTheDocument();
+    expect(screen.getByText(MOCK_VEREIN_DATA.phone)).toBeInTheDocument();
+  });
+
+  it("N1: shows register entry with court and number (legal compliance)", () => {
+    render(<Page />);
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.register.court),
+    ).toBeInTheDocument();
+    expect(
+      screen.getByText(MOCK_VEREIN_DATA.register.number),
+    ).toBeInTheDocument();
+  });
+});

